package com.dy.artisan3d.ui.screen.main.article.detailimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.error_unknownimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.data.mapper.toDomainimport com.dy.artisan3d.data.model.artisan.article.ArtisanArticleSingleResponseimport com.dy.artisan3d.domain.model.NetworkErrorimport com.dy.artisan3d.domain.model.artisan.ArtisanArticleimport com.dy.artisan3d.domain.repository.ArtisanArticleSingleRepositoryimport com.dy.artisan3d.util.toErrorMessageimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.updateimport kotlinx.coroutines.launchclass ArtisanArticleDetailViewModel(    private val artisanArticleSingleRepository: ArtisanArticleSingleRepository,    private val appLanguage: AppLanguage,    private val id: Int): ViewModel() {    private val _uiState = MutableStateFlow(ArtisanSingleArticleUiState())    val uiState = _uiState.asStateFlow()    init {        fetchArticle()    }    fun fetchArticle(){        viewModelScope.launch {            try {                _uiState.update { it.copy(isLoading = true) }                val article = artisanArticleSingleRepository.getByIdArticle(id = id, lang = appLanguage.current)                _uiState.update {                    it.copy(                        artisanArticle = article.getOrThrow(),                        isLoading = false,                        isError = false                    )                }            }catch (e: Exception){                val errorMsg = if (e is NetworkError) {                    e.toErrorMessage()                } else {                    Res.string.error_unknown                }                _uiState.update {                    it.copy(                        isLoading = false,                        isError = true,                        error = errorMsg                    )                }            }        }    }}